<script setup>
import { ref, computed, watch } from 'vue'
import Icon from '../components/Icon.vue'
import Modal from '../components/Modal.vue'
import { store, saveBudget, addCategory, toggleCategory, importExpenses, attempt, notify } from '../store'
import { COLORS, inputMoney, parseMoney, money, dateLabel, fingerprint } from '../lib/domain'
import { readWorkbook, downloadWorkbook } from '../lib/excel'
import { errorMessage } from '../lib/errors'
const budget = ref(inputMoney(store.budgetCents)), name = ref(''), color = ref(COLORS[0]), budgetBusy = ref(false), categoryBusy = ref(false), excelBusy = ref(false), toggling = ref(''), preview = ref(null), fileInput = ref(null)
watch(() => store.budgetCents, value => { if (!budgetBusy.value) budget.value = inputMoney(value) })
const eligible = computed(() => preview.value?.filter(row => !row.error && !row.duplicate) || [])
async function budgetSubmit() { budgetBusy.value = true; await attempt(async () => { await saveBudget(parseMoney(budget.value)); notify('Orçamento atualizado para toda a família.') }); budgetBusy.value = false }
async function categorySubmit() { categoryBusy.value = true; await attempt(async () => { await addCategory(name.value, color.value); name.value = ''; notify('Categoria criada.') }); categoryBusy.value = false }
async function toggle(c) { toggling.value = c.id; await attempt(() => toggleCategory(c)); toggling.value = '' }
async function exportFile(template) { excelBusy.value = true; await attempt(() => downloadWorkbook(store.expenses, store.categories, template)); excelBusy.value = false }
async function readFile(event) { const file = event.target.files[0]; if (!file) return; excelBusy.value = true; await attempt(async () => { preview.value = await readWorkbook(file, store.categories, store.expenses) }); excelBusy.value = false; event.target.value = '' }
async function commitImport() {
  excelBusy.value = true
  try {
    // Outra pessoa pode ter incluído uma despesa desde a abertura da prévia.
    const existing = new Set(store.expenses.map(fingerprint))
    const rows = eligible.value.filter(row => !existing.has(fingerprint(row.expense)))
    if (!rows.length) throw new Error('Todos os registros válidos já estão na lista. Reabra o arquivo para atualizar a prévia.')
    await importExpenses(rows); preview.value = null; notify(`${rows.length} despesas importadas.`)
  } catch (e) { notify(errorMessage(e), 'error') } finally { excelBusy.value = false }
}
</script>
<template>
  <div class="page-heading"><div><h1>Configurações</h1><p class="muted">Ajuste o planejamento e mantenha os dados organizados.</p></div></div>
  <div class="settings-grid"><section class="panel"><div class="panel-heading"><div><h2>Expectativa de gasto</h2><p class="small muted">Orçamento único para toda a reforma</p></div><Icon name="wallet"/></div><form class="form-stack" @submit.prevent="budgetSubmit"><label>Orçamento previsto (R$)<input v-model="budget" inputmode="decimal" required maxlength="20"/></label><p class="hint">Todos os membros podem ajustar este valor. Zero significa orçamento ainda não definido.</p><button class="button fit" :disabled="budgetBusy">{{ budgetBusy ? 'Salvando…' : 'Salvar orçamento' }}</button></form></section>
  <section class="panel"><div class="panel-heading"><div><h2>Categorias</h2><p class="small muted">Uma organização que acompanha sua obra</p></div><Icon name="expenses"/></div><div class="category-settings"><div v-for="c in store.categories" :key="c.id" class="category-setting-row"><span class="legend-dot" :style="{ background: c.color }"/><span>{{ c.name }}<small v-if="!c.active" class="muted"> · Desativada</small></span><button class="text-button" :disabled="!!toggling" @click="toggle(c)">{{ toggling === c.id ? 'Aguarde…' : c.active ? 'Desativar' : 'Reativar' }}</button></div></div><form class="form-stack category-create" @submit.prevent="categorySubmit"><label>Nova categoria<input v-model="name" placeholder="Ex.: Marcenaria" minlength="2" maxlength="60" required/></label><fieldset class="color-picker"><legend>Cor da categoria</legend><label v-for="option in COLORS" :key="option" :style="{ background: option }" :class="{ chosen: color === option }"><input v-model="color" type="radio" :value="option" name="category-color" :aria-label="`Cor ${option}`"/><Icon v-if="color === option" name="check" :size="18"/></label></fieldset><button class="button fit" :disabled="categoryBusy"><Icon name="plus" :size="17"/>{{ categoryBusy ? 'Criando…' : 'Criar categoria' }}</button></form><p class="hint">Desativar preserva o histórico. A categoria deixa de aparecer em novos lançamentos.</p></section>
  <section class="panel excel-panel"><div class="panel-heading"><div><h2>Seus dados também no Excel</h2><p class="small muted">Exporte para guardar ou importe novos registros.</p></div><Icon name="excel" :size="25"/></div><div class="excel-options"><div><h3>Exportar despesas</h3><p class="muted small">Baixe todos os gastos com categorias e informações de parcelas.</p><button class="button secondary" :disabled="excelBusy" @click="exportFile(false)"><Icon name="download" :size="17"/>Exportar tudo</button></div><div><h3>Importar uma planilha</h3><p class="muted small">Use nosso modelo .xlsx. Até 400 registros e 2 MB por arquivo.</p><div class="inline wrap"><button class="button secondary" :disabled="excelBusy" @click="exportFile(true)">Baixar modelo</button><button class="button" :disabled="excelBusy" @click="fileInput.click()"><Icon name="upload" :size="17"/>{{ excelBusy ? 'Processando…' : 'Escolher arquivo' }}</button></div><input ref="fileInput" class="sr-only" type="file" accept=".xlsx" aria-label="Selecionar Excel para importação" @change="readFile"/></div></div><p class="hint">A importação adiciona despesas. Não atualiza registros existentes. Linhas inválidas e possíveis duplicidades serão ignoradas após sua revisão.</p></section></div>
  <Modal v-if="preview" title="Revisar importação" wide :busy="excelBusy" @close="!excelBusy && (preview = null)"><p class="muted">{{ eligible.length }} válidos · {{ preview.filter(r => r.error).length }} com erro · {{ preview.filter(r => r.duplicate).length }} possíveis duplicidades</p><div class="import-preview"><table><thead><tr><th>Linha</th><th>Despesa</th><th>Valor</th><th>Resultado</th></tr></thead><tbody><tr v-for="row in preview" :key="row.line"><td>{{ row.line }}</td><td>{{ row.expense?.description || '—' }}<small class="muted block">{{ row.expense ? dateLabel(row.expense.date) : '' }}</small></td><td>{{ row.expense ? money(row.expense.amountCents) : '—' }}</td><td :class="{ 'danger-text': row.error }">{{ row.error || (row.duplicate ? 'Duplicidade: será ignorada' : 'Pronta para importar') }}</td></tr></tbody></table></div><p class="hint">Confira especialmente a linha de exemplo do modelo antes de confirmar.</p><div class="modal-actions"><button class="button secondary" :disabled="excelBusy" @click="preview = null">Cancelar</button><button class="button" :disabled="excelBusy || !eligible.length" @click="commitImport">{{ excelBusy ? 'Importando…' : `Importar ${eligible.length} despesas válidas` }}</button></div></Modal>
</template>
